package org.jlinalg.cli;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Real global executions,failed output admission,replay and resealed contradictions. */
final class AcatToolsCliTest {
    record Call(int code,String output,String error){ }
    private static Call call(String... args){var out=new ByteArrayOutputStream();var err=new ByteArrayOutputStream();int code=JLinAlgCli.run(args,new PrintStream(out,true,StandardCharsets.UTF_8),new PrintStream(err,true,StandardCharsets.UTF_8));return new Call(code,out.toString(StandardCharsets.UTF_8),err.toString(StandardCharsets.UTF_8));}
    private static Path root()throws Exception {return Files.createDirectories(Path.of("build/acat091-cli-test-captures/"+UUID.randomUUID()).toAbsolutePath());}
    private static Map<String,Object> request(Path out){var request=new LinkedHashMap<String,Object>();request.put("schema_version",1);request.put("mode","RUN");request.put("engine","native");request.put("profile","0.91");request.put("operation","COMBINE");request.put("out",out.toString());request.put("p_values",List.of(List.of(.02,.1),List.of(.0004,.2),List.of(.2,.8),List.of(.1,.4),List.of(.8,.3)));request.put("column_ids",List.of(" literal ID ","gene-α"));return request;}
    private static Path write(Path directory,String name,Map<String,Object> request)throws Exception {Path path=directory.resolve(name);Files.write(path,RsemJson.bytes(request));return path;}
    private static Path run(Path directory,Map<String,Object> request,int expected)throws Exception {Call result=call("acat-tools","--request",write(directory,"request-"+UUID.randomUUID()+".json",request).toString());assertEquals(expected,result.code(),result.error());return Path.of(request.get("out").toString());}
    private static Map<String,Object> object(Path path)throws Exception {Object value=SimpleJson.parse(Files.readString(path));var result=new LinkedHashMap<String,Object>();for(var entry:((Map<?,?>)value).entrySet())result.put(entry.getKey().toString(),entry.getValue());return result;}
    private static void reseal(Path capture)throws Exception {var inventory=new TreeMap<String,Object>();try(var paths=Files.walk(capture)){for(Path path:paths.toList())if(Files.isRegularFile(path)&&!path.equals(capture.resolve("capture-files.json"))){byte[] raw=Files.readAllBytes(path);inventory.put(capture.relativize(path).toString().replace('\\','/'),Map.of("bytes",raw.length,"sha256",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw))));}}Files.write(capture.resolve("capture-files.json"),RsemJson.bytes(inventory));}

    @Test void globalCommandActuallyComputesBothColumnsAndVerifies()throws Exception {Path directory=root(),capture=run(directory,request(directory.resolve("capture")),0);String text=Files.readString(capture.resolve("p-values.tsv"));assertTrue(text.contains(" literal ID "));assertTrue(text.contains("gene-α"));double p=Double.parseDouble(text.split("\n")[1].split("\t")[2]);assertEquals(.0019534044057701767,p,1e-16);assertEquals(0,call("acat-tools","--verify",capture.toString()).code());assertEquals(Boolean.FALSE,object(capture.resolve("analysis-status.json")).get("original_R_executed"));}
    @Test void replayExecutesNewOutputAndPreservesTheParentSeal()throws Exception {Path directory=root(),capture=run(directory,request(directory.resolve("parent")),0),next=directory.resolve("replay");byte[] seal=Files.readAllBytes(capture.resolve("capture-files.json"));var control=Map.<String,Object>of("schema_version",1,"mode","REPLAY","analysis",capture.toString(),"out",next.toString());Call result=call("acat-tools","--request",write(directory,"replay.json",control).toString());assertEquals(0,result.code(),result.error());assertArrayEquals(Files.readAllBytes(capture.resolve("p-values.tsv")),Files.readAllBytes(next.resolve("p-values.tsv")));assertArrayEquals(seal,Files.readAllBytes(capture.resolve("capture-files.json")));assertEquals(0,call("acat-tools","--verify",next.toString()).code());}
    @Test void sourceEndpointWarningsAreProminentWithoutReplacingTheInputs()throws Exception {Path directory=root();var request=request(directory.resolve("capture"));request.put("p_values",List.of(List.of(0,1),List.of(.1,.2)));Path capture=run(directory,request,0);String warning=Files.readString(capture.resolve("WARNINGS.md"));assertTrue(warning.contains("exactly 0"));assertTrue(warning.contains("exactly 1"));assertTrue(warning.contains("numeric zero"));assertEquals("COMPLETED_WITH_WARNINGS",object(capture.resolve("analysis-status.json")).get("status"));}
    @Test void nonfiniteZeroWeightEndpointReturnIsRetainedAndNoExportAdmitted()throws Exception {Path directory=root();var request=request(directory.resolve("capture"));request.put("p_values",List.of(List.of(0),List.of(.1)));request.put("weights",List.of(List.of(0),List.of(1)));request.remove("column_ids");Path capture=run(directory,request,2);assertFalse(Files.exists(capture.resolve("p-values.tsv")));assertTrue(Files.readString(capture.resolve("native-result.json")).contains("NaN"));assertEquals(0,call("acat-tools","--verify",capture.toString()).code());}
    @Test void opposingEndpointsRefuseBeforeTheSourceWarnings()throws Exception {Path directory=root();var request=request(directory.resolve("capture"));request.put("p_values",List.of(List.of(0),List.of(1)));request.put("weights",List.of(List.of(1),List.of(0)));request.remove("column_ids");Path capture=run(directory,request,2);assertTrue(Files.readString(capture.resolve("native-result.json")).contains("Cannot have both 0 and 1"));assertEquals(List.of(),object(capture.resolve("native-result.json")).get("source_warnings"));}
    @Test void finiteRawProbabilityFromOverflowIsUnadmitted()throws Exception {Path directory=root();var request=request(directory.resolve("capture"));request.put("p_values",List.of(List.of(.01),List.of(.8)));request.put("weights",List.of(List.of(1e308),List.of(1e308)));request.remove("column_ids");Path capture=run(directory,request,2);assertTrue(Files.readString(capture.resolve("native-result.json")).contains("0.5"));assertFalse(Files.exists(capture.resolve("p-values.tsv")));assertEquals(0,call("acat-tools","--verify",capture.toString()).code());}
    @Test void resealedChangedSourceIsStillRefused()throws Exception {Path directory=root(),capture=run(directory,request(directory.resolve("capture")),0);Files.writeString(capture.resolve("source/R/ACAT.R"),"\n# deliberately changed\n",StandardOpenOption.APPEND);reseal(capture);Call result=call("acat-tools","--verify",capture.toString());assertEquals(2,result.code());assertTrue(result.error().contains("Changed captured source"));}
    @Test void resealedChangedValueIsRefusedByCompleteRecomputation()throws Exception {Path directory=root(),capture=run(directory,request(directory.resolve("capture")),0);String text=Files.readString(capture.resolve("native-result.json"));assertTrue(text.contains("raw_source_profile_p"));Files.writeString(capture.resolve("native-result.json"),text.replace("raw_source_profile_p","changed_source_profile_p"));reseal(capture);Call result=call("acat-tools","--verify",capture.toString());assertEquals(2,result.code());assertTrue(result.error().contains("Complete native recomputation"));}
    @Test void resealedFalseEditionInStatusIsRefused()throws Exception {Path directory=root(),capture=run(directory,request(directory.resolve("capture")),0);var status=object(capture.resolve("analysis-status.json"));status.put("profile","1.0");Files.write(capture.resolve("analysis-status.json"),RsemJson.bytes(status));reseal(capture);Call result=call("acat-tools","--verify",capture.toString());assertEquals(2,result.code());assertTrue(result.error().contains("Completion/admission state"));}
    @Test void resealedDifferentImplementationClassesAreRefused()throws Exception {Path directory=root(),capture=run(directory,request(directory.resolve("capture")),0);Files.writeString(capture.resolve("implementation-classes.json"),"{}\n");reseal(capture);Call result=call("acat-tools","--verify",capture.toString());assertEquals(2,result.code());assertTrue(result.error().contains("implementation classes"));}
    @Test void anUnadmittedBatchCannotAcquireAnExportByResealing()throws Exception {Path directory=root();var request=request(directory.resolve("capture"));request.put("p_values",List.of(List.of(0),List.of(.1)));request.put("weights",List.of(List.of(0),List.of(1)));request.remove("column_ids");Path capture=run(directory,request,2);Files.writeString(capture.resolve("p-values.tsv"),"fake positive result\n");reseal(capture);Call result=call("acat-tools","--verify",capture.toString());assertEquals(2,result.code());assertTrue(result.error().contains("Unadmitted batch carries a result export"));}
    @Test void existingOutputIsPreserved()throws Exception {Path directory=root();var request=request(directory.resolve("capture"));Path capture=run(directory,request,0);byte[] seal=Files.readAllBytes(capture.resolve("capture-files.json"));Call result=call("acat-tools","--request",write(directory,"again.json",request).toString());assertEquals(2,result.code());assertArrayEquals(seal,Files.readAllBytes(capture.resolve("capture-files.json")));}
    @Test void aChangedOrExtraFileCannotPassTheSeal()throws Exception {Path directory=root(),capture=run(directory,request(directory.resolve("capture")),0);Files.writeString(capture.resolve("unrecorded.txt"),"extra\n");Call result=call("acat-tools","--verify",capture.toString());assertEquals(2,result.code());assertTrue(result.error().contains("Changed/missing/extra"));}
    @Test void cellAndColumnCapacitiesRefuseWithoutPartialExport()throws Exception {Path directory=root();var request=request(directory.resolve("capture"));request.put("limits",Map.of("maximum_cells",2));Path capture=run(directory,request,2);assertTrue(Files.readString(capture.resolve("WARNINGS.md")).contains("capacity"));assertFalse(Files.exists(capture.resolve("p-values.tsv")));}
    @Test void unknownFieldsAndAlternateOperationsAreRefused()throws Exception {Path directory=root();var request=request(directory.resolve("capture"));request.put("operation","ACAT_V");Path capture=run(directory,request,2);assertFalse(Files.exists(capture.resolve("p-values.tsv")));assertTrue(Files.readString(capture.resolve("WARNINGS.md")).contains("operation COMBINE"));}
    @Test void invalidLiteralColumnIdentifiersAreNotRepaired()throws Exception {Path directory=root();var request=request(directory.resolve("capture"));request.put("column_ids",List.of("x","x"));Path capture=run(directory,request,2);assertTrue(Files.readString(capture.resolve("WARNINGS.md")).contains("no trimming or repair"));}
    @Test void stringsAreNotCoercedIntoProbabilityNumbers()throws Exception {Path directory=root();var request=request(directory.resolve("capture"));request.put("p_values",List.of(List.of("NaN")));request.remove("column_ids");Path capture=run(directory,request,2);assertTrue(Files.readString(capture.resolve("WARNINGS.md")).contains("no parsing or repair"));}
    @Test void replayInsideParentIsRefusedWithoutMutation()throws Exception {Path directory=root(),capture=run(directory,request(directory.resolve("capture")),0);byte[] seal=Files.readAllBytes(capture.resolve("capture-files.json"));var control=Map.<String,Object>of("schema_version",1,"mode","REPLAY","analysis",capture.toString(),"out",capture.resolve("nested").toString());assertEquals(2,call("acat-tools","--request",write(directory,"replay-invalid.json",control).toString()).code());assertArrayEquals(seal,Files.readAllBytes(capture.resolve("capture-files.json")));}
    @Test void replayThroughAnOwnedDirectoryAliasCannotMutateItsParent()throws Exception {
        Path directory=root(),capture=run(directory,request(directory.resolve("capture")),0),alias=directory.resolve("alias");byte[] seal=Files.readAllBytes(capture.resolve("capture-files.json"));
        if(System.getProperty("os.name").toLowerCase(java.util.Locale.ROOT).startsWith("windows")){
            var process=new ProcessBuilder("cmd.exe","/c","mklink","/J",alias.toString(),capture.toString()).redirectErrorStream(true).start();String message=new String(process.getInputStream().readAllBytes(),StandardCharsets.UTF_8);assertEquals(0,process.waitFor(),message);
        }else Files.createSymbolicLink(alias,capture);
        assertEquals(capture.toRealPath(),alias.toRealPath());var control=Map.<String,Object>of("schema_version",1,"mode","REPLAY","analysis",capture.toString(),"out",alias.resolve("nested").toString());Call result=call("acat-tools","--request",write(directory,"replay-alias.json",control).toString());assertEquals(2,result.code());assertTrue(result.error().contains("outside its parent capture"));assertFalse(Files.exists(capture.resolve("nested")));assertArrayEquals(seal,Files.readAllBytes(capture.resolve("capture-files.json")));assertEquals(0,call("acat-tools","--verify",capture.toString()).code());
    }
}
